.darma-loader-darma-b14-snow-globe { --accent: var(--loader-color, #16a34a); --accent-2: var(--loader-secondary-color, #60a5fa); width: var(--loader-size, 108px); height: var(--loader-size, 108px); position: relative; display: grid; place-items: start center; }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome { position: relative; width: 84%; height: 78%; overflow: hidden; border-radius: 50%; background: radial-gradient(circle at 34% 26%, rgba(255, 255, 255, .6), color-mix(in srgb, #fff 30%, var(--accent-2)) 46%, color-mix(in srgb, #000 14%, var(--accent-2))); }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome::after { content: ''; position: absolute; bottom: 4%; left: 38%; width: 24%; height: 38%; clip-path: polygon(50% 0, 100% 100%, 0 100%); background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome span { position: absolute; width: 9%; height: 9%; border-radius: 50%; background: rgba(255, 255, 255, .95); animation: darma-loader-darma-b14-snow-globe-snowfall calc(var(--loader-speed, 1s) * 2.8) linear infinite; }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome span:nth-child(1) { left: 18%; }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome span:nth-child(2) { left: 36%; animation-delay: calc(var(--loader-speed, 1s) * -.56); }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome span:nth-child(3) { left: 52%; animation-delay: calc(var(--loader-speed, 1s) * -1.12); }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome span:nth-child(4) { left: 68%; animation-delay: calc(var(--loader-speed, 1s) * -1.68); }
.darma-loader-darma-b14-snow-globe .darma-loader-darma-b14-snow-globe__dome span:nth-child(5) { left: 82%; animation-delay: calc(var(--loader-speed, 1s) * -2.24); }
.darma-loader-darma-b14-snow-globe::after { content: ''; position: absolute; bottom: 2%; left: 18%; width: 64%; height: 17%; border-radius: 4px 4px 9px 9px; background: linear-gradient(color-mix(in srgb, #000 22%, var(--accent-2)), color-mix(in srgb, #000 48%, var(--accent-2))); }
@keyframes darma-loader-darma-b14-snow-globe-snowfall { 0% { opacity: 0; transform: translate(0, -20%); } 12% { opacity: 1; } 88% { opacity: 1; } 100% { opacity: 0; transform: translate(-40%, 320%); } }

